// Emit Lingua Tungga packages from the schema IR.
//
// The emitter is pure: it returns a map of file name -> content. The CLI is
// responsible for writing, checking, and cleaning stale generated files.

import {
    enumColumnTypeName,
    enumPackageName,
    enumValueFunctionName,
    ltString,
    tableTypeName,
    toSnakeCase,
} from "./naming.ts";
import {
    type ColumnIR,
    type DefaultIR,
    type EnumIR,
    type ForeignKeyIR,
    type SchemaIR,
    type SemanticType,
    type TableIR,
} from "./types.ts";

export type EmittedFile = {
    name: string;
    content: string;
};

type ScalarSpec = {
    type: Exclude<SemanticType, "Enum" | "Unsupported">;
    columnType: string;
    valueType: string;
    packageName: string;
    param: string;
    pattern: boolean;
    ordered: boolean;
};

const SCALAR_SPECS: ScalarSpec[] = [
    {
        type: "Int",
        columnType: "IntColumn",
        valueType: "Int",
        packageName: "schema_int",
        param: "Scalar.Int",
        pattern: false,
        ordered: true,
    },
    {
        type: "Float",
        columnType: "FloatColumn",
        valueType: "Float",
        packageName: "schema_float",
        param: "Scalar.Float",
        pattern: false,
        ordered: true,
    },
    {
        type: "Str",
        columnType: "StrColumn",
        valueType: "Str",
        packageName: "schema_str",
        param: "Scalar.Text",
        pattern: true,
        ordered: true,
    },
    {
        type: "Bool",
        columnType: "BoolColumn",
        valueType: "Bool",
        packageName: "schema_bool",
        param: "Scalar.Bool",
        pattern: false,
        ordered: false,
    },
    {
        type: "Decimal",
        columnType: "DecimalColumn",
        valueType: "Str",
        packageName: "schema_decimal",
        param: "Scalar.Text",
        pattern: false,
        ordered: true,
    },
    {
        type: "Uuid",
        columnType: "UuidColumn",
        valueType: "Str",
        packageName: "schema_uuid",
        param: "Scalar.Text",
        pattern: false,
        ordered: true,
    },
    {
        type: "Temporal",
        columnType: "TemporalColumn",
        valueType: "Str",
        packageName: "schema_temporal",
        param: "Scalar.Text",
        pattern: false,
        ordered: true,
    },
];

const SCALAR_BY_TYPE = new Map<SemanticType, ScalarSpec>(
    SCALAR_SPECS.map((spec) => [spec.type, spec]),
);

function header(source: string): string {
    return `// Generated by @gntrees/sql-builder schema codegen. Do not edit.
// Source: ${source} (version 1).
`;
}

function columnTypeFor(column: ColumnIR): string {
    if (column.type === "Unsupported") return "UnsupportedColumn";
    if (column.type === "Enum") {
        if (!column.enum) throw new Error(`column ${column.name}: enum type is missing`);
        const base = enumColumnTypeName(column.enum);
        return column.nullable ? `Nullable${base}` : base;
    }
    const base = SCALAR_BY_TYPE.get(column.type)!.columnType;
    return column.nullable ? `Nullable${base}` : base;
}

function packageFor(column: ColumnIR): string {
    if (column.type === "Unsupported") return "schema_unsupported";
    if (column.type === "Enum") {
        if (!column.enum) throw new Error(`column ${column.name}: enum type is missing`);
        const base = enumPackageName(column.enum);
        return column.nullable ? `${base}_nullable` : base;
    }
    const base = SCALAR_BY_TYPE.get(column.type)!.packageName;
    return column.nullable ? base.replace(/^schema_/, "schema_nullable_") : base;
}

function exprPackage(): EmittedFile {
    const content = `${header("schema/schema.json")}package schema_expr {
  export struct ColumnRef {
    table: Str
    column: Str
    sql_type: Str
    nullable: Bool
  }

  export enum Scalar {
    Null
    Int(Int)
    Float(Float)
    Bool(Bool)
    Text(Str)
  }

  /// Nilai untuk INSERT/UPDATE: nama kolom SQL + scalar netral.
  export struct ColumnValue {
    column: Str
    value: Scalar
  }

  export enum Expr {
    Column(ColumnRef)
    Param(Scalar)
    Eq(Expr, Expr)
    Ne(Expr, Expr)
    IsDistinct(Expr, Expr)
    IsNotDistinct(Expr, Expr)
    Gt(Expr, Expr)
    Gte(Expr, Expr)
    Lt(Expr, Expr)
    Lte(Expr, Expr)
    IsNull(Expr)
    IsNotNull(Expr)
    Like(Expr, Expr)
    ILike(Expr, Expr)
    In(Expr, List<Expr>)
    NotIn(Expr, List<Expr>)
    Between(Expr, Expr, Expr)
    NotBetween(Expr, Expr, Expr)
    And(List<Expr>)
    Or(List<Expr>)
    Not(Expr)
    Asc(Expr)
    Desc(Expr)
    Alias(Expr, Str)
    Raw(Str)
  }

  export fn all_of(items: List<Expr>) -> Expr {
    Expr.And(items)
  }

  export fn any_of(items: List<Expr>) -> Expr {
    Expr.Or(items)
  }

  export fn negate(expr: Expr) -> Expr {
    Expr.Not(expr)
  }

  export fn raw(text: Str) -> Expr {
    Expr.Raw(text)
  }
}
`;
    return { name: "schema_expr.lt", content };
}

function scalarPackage(spec: ScalarSpec, nullable = false): EmittedFile {
    const columnType = nullable ? `Nullable${spec.columnType}` : spec.columnType;
    const packageName = nullable
        ? spec.packageName.replace(/^schema_/, "schema_nullable_")
        : spec.packageName;
    const lines: string[] = [];
    const push = (line = "") => lines.push(line);

    push(`export struct ${columnType} {`);
    push("  table: Str");
    push("  column: Str");
    push("  nullable: Bool");
    push("}");
    push();

    push(`fn ref(c: ${columnType}) -> ColumnRef {`);
    push(`  ColumnRef(table: c.table, column: c.column, sql_type: ${ltString(spec.type)}, nullable: c.nullable)`);
    push("}");
    push();

    push(`fn col(c: ${columnType}) -> Expr {`);
    push("  Expr.Column(ref(c))");
    push("}");
    push();

    push(`fn param(v: ${spec.valueType}) -> Expr {`);
    push(`  Expr.Param(${spec.param}(v))`);
    push("}");
    push();

    if (nullable) {
        push(`export fn assign(c: ${columnType}, v: Option<${spec.valueType}>) -> ColumnValue {`);
        push("  match v {");
        push(`    Some(item) => ColumnValue(column: c.column, value: ${spec.param}(item))`);
        push("    None => ColumnValue(column: c.column, value: Scalar.Null)");
        push("  }");
        push("}");
        push();
    } else {
        push(`export fn assign(c: ${columnType}, v: ${spec.valueType}) -> ColumnValue {`);
        push(`  ColumnValue(column: c.column, value: ${spec.param}(v))`);
        push("}");
        push();
    }

    push(`export fn assign_null(c: ${columnType}) -> ColumnValue {`);
    push("  ColumnValue(column: c.column, value: Scalar.Null)");
    push("}");
    push();

    const binary = (name: string, variant: string) => {
        push(`export fn ${name}(c: ${columnType}, v: ${spec.valueType}) -> Expr {`);
        push(`  Expr.${variant}(col(c), param(v))`);
        push("}");
        push();
    };

    binary("eq", "Eq");
    binary("ne", "Ne");
    binary("is_distinct_from", "IsDistinct");
    binary("is_not_distinct_from", "IsNotDistinct");

    if (spec.ordered) {
        binary("gt", "Gt");
        binary("gte", "Gte");
        binary("lt", "Lt");
        binary("lte", "Lte");

        push(`export fn in_list(c: ${columnType}, values: List<${spec.valueType}>) -> Expr {`);
        push("  Expr.In(col(c), values.map(fn(v) => param(v)))");
        push("}");
        push();

        push(`export fn not_in_list(c: ${columnType}, values: List<${spec.valueType}>) -> Expr {`);
        push("  Expr.NotIn(col(c), values.map(fn(v) => param(v)))");
        push("}");
        push();

        push(`export fn between(c: ${columnType}, low: ${spec.valueType}, high: ${spec.valueType}) -> Expr {`);
        push("  Expr.Between(col(c), param(low), param(high))");
        push("}");
        push();

        push(`export fn not_between(c: ${columnType}, low: ${spec.valueType}, high: ${spec.valueType}) -> Expr {`);
        push("  Expr.NotBetween(col(c), param(low), param(high))");
        push("}");
        push();
    }

    if (spec.pattern) {
        push(`export fn like(c: ${columnType}, v: ${spec.valueType}) -> Expr {`);
        push("  Expr.Like(col(c), param(v))");
        push("}");
        push();
        push(`export fn not_like(c: ${columnType}, v: ${spec.valueType}) -> Expr {`);
        push("  Expr.Not(Expr.Like(col(c), param(v)))");
        push("}");
        push();
        push(`export fn ilike(c: ${columnType}, v: ${spec.valueType}) -> Expr {`);
        push("  Expr.ILike(col(c), param(v))");
        push("}");
        push();
        push(`export fn not_ilike(c: ${columnType}, v: ${spec.valueType}) -> Expr {`);
        push("  Expr.Not(Expr.ILike(col(c), param(v)))");
        push("}");
        push();
    }

    push(`export fn is_null(c: ${columnType}) -> Expr {`);
    push("  Expr.IsNull(col(c))");
    push("}");
    push();

    push(`export fn is_not_null(c: ${columnType}) -> Expr {`);
    push("  Expr.IsNotNull(col(c))");
    push("}");
    push();

    push(`export fn asc(c: ${columnType}) -> Expr {`);
    push("  Expr.Asc(col(c))");
    push("}");
    push();

    push(`export fn desc(c: ${columnType}) -> Expr {`);
    push("  Expr.Desc(col(c))");
    push("}");
    push();

    push(`export fn as_alias(c: ${columnType}, alias: Str) -> Expr {`);
    push("  Expr.Alias(col(c), alias)");
    push("}");
    push();

    const content = `${header("schema/schema.json")}import schema_expr { ColumnValue, Expr, ColumnRef, Scalar } "./schema_expr.lt"

package ${packageName} {
${lines.map((line) => (line.length > 0 ? `  ${line}` : "")).join("\n")}}
`;
    return { name: `${packageName}.lt`, content };
}

function enumPackage(item: EnumIR, nullable = false): EmittedFile {
    const columnType = nullable
        ? `Nullable${enumColumnTypeName(item.name)}`
        : enumColumnTypeName(item.name);
    const packageName = nullable ? `${item.package}_nullable` : item.package;
    const valueFn = enumValueFunctionName(item.name);
    const lines: string[] = [];
    const push = (line = "") => lines.push(line);

    push(`export enum ${item.name} {`);
    for (const value of item.values) push(`  ${value.name}`);
    push("}");
    push();

    push(`export fn ${valueFn}(value: ${item.name}) -> Str {`);
    push("  match value {");
    for (const value of item.values) {
        push(`    ${item.name}.${value.name} => ${ltString(value.dbName)}`);
    }
    push("  }");
    push("}");
    push();

    push(`export struct ${columnType} {`);
    push("  table: Str");
    push("  column: Str");
    push("  nullable: Bool");
    push("}");
    push();

    push(`fn ref(c: ${columnType}) -> ColumnRef {`);
    push(`  ColumnRef(table: c.table, column: c.column, sql_type: "Enum", nullable: c.nullable)`);
    push("}");
    push();

    push(`fn col(c: ${columnType}) -> Expr {`);
    push("  Expr.Column(ref(c))");
    push("}");
    push();

    push(`fn param(v: ${item.name}) -> Expr {`);
    push(`  Expr.Param(Scalar.Text(${valueFn}(v)))`);
    push("}");
    push();

    if (nullable) {
        push(`export fn assign(c: ${columnType}, v: Option<${item.name}>) -> ColumnValue {`);
        push("  match v {");
        push(`    Some(item) => ColumnValue(column: c.column, value: Scalar.Text(${valueFn}(item)))`);
        push("    None => ColumnValue(column: c.column, value: Scalar.Null)");
        push("  }");
        push("}");
        push();
    } else {
        push(`export fn assign(c: ${columnType}, v: ${item.name}) -> ColumnValue {`);
        push(`  ColumnValue(column: c.column, value: Scalar.Text(${valueFn}(v)))`);
        push("}");
        push();
    }

    push(`export fn assign_null(c: ${columnType}) -> ColumnValue {`);
    push("  ColumnValue(column: c.column, value: Scalar.Null)");
    push("}");
    push();

    push(`export fn eq(c: ${columnType}, v: ${item.name}) -> Expr {`);
    push("  Expr.Eq(col(c), param(v))");
    push("}");
    push();

    push(`export fn ne(c: ${columnType}, v: ${item.name}) -> Expr {`);
    push("  Expr.Ne(col(c), param(v))");
    push("}");
    push();

    push(`export fn is_distinct_from(c: ${columnType}, v: ${item.name}) -> Expr {`);
    push("  Expr.IsDistinct(col(c), param(v))");
    push("}");
    push();

    push(`export fn is_not_distinct_from(c: ${columnType}, v: ${item.name}) -> Expr {`);
    push("  Expr.IsNotDistinct(col(c), param(v))");
    push("}");
    push();

    push(`export fn in_list(c: ${columnType}, values: List<${item.name}>) -> Expr {`);
    push("  Expr.In(col(c), values.map(fn(v) => param(v)))");
    push("}");
    push();

    push(`export fn not_in_list(c: ${columnType}, values: List<${item.name}>) -> Expr {`);
    push("  Expr.NotIn(col(c), values.map(fn(v) => param(v)))");
    push("}");
    push();

    push(`export fn is_null(c: ${columnType}) -> Expr {`);
    push("  Expr.IsNull(col(c))");
    push("}");
    push();

    push(`export fn is_not_null(c: ${columnType}) -> Expr {`);
    push("  Expr.IsNotNull(col(c))");
    push("}");
    push();

    push(`export fn as_alias(c: ${columnType}, alias: Str) -> Expr {`);
    push("  Expr.Alias(col(c), alias)");
    push("}");
    push();

    const content = `${header("schema/schema.json")}import schema_expr { ColumnValue, Expr, ColumnRef, Scalar } "./schema_expr.lt"

package ${packageName} {
${lines.map((line) => (line.length > 0 ? `  ${line}` : "")).join("\n")}}
`;
    return { name: `${packageName}.lt`, content };
}

function unsupportedPackage(): EmittedFile {
    const content = `${header("schema/schema.json")}package schema_unsupported {
  export struct UnsupportedColumn {
    table: Str
    column: Str
    sql_type: Str
    nullable: Bool
  }
}
`;
    return { name: "schema_unsupported.lt", content };
}

function metaPackage(): EmittedFile {
    const content = `${header("schema/schema.json")}package schema_meta {
  export struct ColumnMeta {
    name: Str
    db_name: Str
    sql_type: Str
    nullable: Bool
    primary: Bool
    unique: Bool
    has_default: Bool
    default_sql: Str
  }

  export struct TableMeta {
    name: Str
    db_name: Str
    schema: Str
    primary_key: List<Str>
    columns: List<ColumnMeta>
    indexes: List<IndexMeta>
  }

  export struct IndexMeta {
    name: Str
    columns: List<Str>
    unique: Bool
  }
}
`;
    return { name: "schema_meta.lt", content };
}

function defaultSql(value: DefaultIR | undefined): string {
    if (!value) return "";
    switch (value.kind) {
        case "autoincrement":
            return "autoincrement";
        case "now":
            return "now()";
        case "uuid":
            return value.version ? `uuid(${value.version})` : "uuid()";
        case "cuid":
            return value.version ? `cuid(${value.version})` : "cuid()";
        case "dbgenerated":
            return value.value;
        case "literal":
            return typeof value.value === "string" ? ltString(value.value) : String(value.value);
        case "function":
            return `${value.name}(${value.args.join(", ")})`;
        case "unknown":
            return value.value;
    }
}

function columnValue(column: ColumnIR): string {
    if (column.type === "Unsupported") {
        return `UnsupportedColumn(table: ${ltString("")}, column: ${ltString(column.dbName)}, sql_type: ${ltString(column.nativeType)}, nullable: ${column.nullable})`;
    }
    return `${columnTypeFor(column)}(table: "", column: ${ltString(column.dbName)}, nullable: ${column.nullable})`;
}

function tablesPackage(schema: SchemaIR): EmittedFile | undefined {
    if (schema.tables.length === 0) return undefined;

    const imports = new Map<string, Set<string>>();
    for (const table of schema.tables) {
        for (const column of table.columns) {
            const pkg = packageFor(column);
            const types = imports.get(pkg) ?? new Set<string>();
            types.add(columnTypeFor(column));
            imports.set(pkg, types);
        }
    }

    const importLines = [
        ...imports.entries()
            .map(([pkg, types]) => `import ${pkg} { ${[...types].sort().join(", ")} } "./${pkg}.lt"`),
        `import schema_meta { ColumnMeta, IndexMeta, TableMeta } "./schema_meta.lt"`,
    ]
        .sort()
        .join("\n");

    const body: string[] = [];
    for (const table of schema.tables) {
        const typeName = tableTypeName(table.name);
        body.push(`export struct ${typeName} {`);
        for (const column of table.columns) {
            body.push(`  ${column.name}: ${columnTypeFor(column)}`);
        }
        body.push("}");
        body.push("");
    }

    for (const table of schema.tables) {
        const typeName = tableTypeName(table.name);
        const fields = table.columns.map((column) => {
            const value = columnValue(column).replace('table: ""', `table: ${ltString(table.dbName)}`);
            return `  ${column.name}: ${value},`;
        });
        body.push(`export let ${table.name}: ${typeName} = ${typeName}(`);
        body.push(...fields);
        body.push(")");
        body.push("");
    }

    for (const table of schema.tables) {
        body.push(`export let ${table.name}_meta: TableMeta = TableMeta(`);
        body.push(`  name: ${ltString(table.name)},`);
        body.push(`  db_name: ${ltString(table.dbName)},`);
        body.push(`  schema: ${ltString(table.schema)},`);
        body.push(`  primary_key: [${table.primaryKey.map((name) => ltString(name)).join(", ")}],`);
        body.push("  columns: [");
        for (const column of table.columns) {
            body.push("    ColumnMeta(");
            body.push(`      name: ${ltString(column.name)},`);
            body.push(`      db_name: ${ltString(column.dbName)},`);
            body.push(`      sql_type: ${ltString(column.nativeType)},`);
            body.push(`      nullable: ${column.nullable},`);
            body.push(`      primary: ${table.primaryKey.includes(column.name)},`);
            body.push(`      unique: ${column.unique},`);
            body.push(`      has_default: ${column.default !== undefined},`);
            body.push(`      default_sql: ${ltString(defaultSql(column.default))},`);
            body.push("    ),");
        }
        body.push("  ],");
        if (table.indexes.length === 0) {
            body.push("  indexes: [],");
        } else {
            body.push("  indexes: [");
            for (const index of table.indexes) {
                body.push("    IndexMeta(");
                body.push(`      name: ${ltString(index.name)},`);
                body.push(`      columns: [${index.columns.map((column) => ltString(column)).join(", ")}],`);
                body.push(`      unique: ${index.unique},`);
                body.push("    ),");
            }
            body.push("  ],");
        }
        body.push(")");
        body.push("");
    }

    if (schema.tables.some((table) => table.name === "all_table_meta")) {
        throw new Error('table name "all_table_meta" collides with the generated metadata list');
    }
    body.push("export let all_table_meta: List<TableMeta> = [");
    for (const table of schema.tables) body.push(`  ${table.name}_meta,`);
    body.push("]");
    body.push("");

    const content = `${header("schema/schema.json")}${importLines}

package schema_tables {
${body.map((line) => (line.length > 0 ? `  ${line}` : "")).join("\n")}}
`;
    return { name: "schema_tables.lt", content };
}

function relationsPackage(schema: SchemaIR): EmittedFile | undefined {
    if (schema.foreignKeys.length === 0) return undefined;

    const tableByName = new Map(schema.tables.map((table) => [table.name, table]));

    // Two foreign keys between the same pair of tables would produce the same
    // binding name, so the owning column is appended to disambiguate them.
    const pairCount = new Map<string, number>();
    for (const fk of schema.foreignKeys) {
        const key = `${fk.fromTable}\u0000${fk.toTable}`;
        pairCount.set(key, (pairCount.get(key) ?? 0) + 1);
    }

    type Binding = {
        name: string;
        fk: ForeignKeyIR;
        from: TableIR;
        to: TableIR;
        fromColumns: ColumnIR[];
        toColumns: ColumnIR[];
        composite: boolean;
    };

    const bindings: Binding[] = [];
    const used = new Set<string>([
        "all_relations",
        "all_composite_relations",
        "relation_meta",
        "composite_relation_meta",
    ]);

    for (const fk of schema.foreignKeys) {
        const from = tableByName.get(fk.fromTable);
        const to = tableByName.get(fk.toTable);
        if (!from) throw new Error(`foreign key ${fk.name}: unknown table "${fk.fromTable}"`);
        if (!to) throw new Error(`foreign key ${fk.name}: unknown table "${fk.toTable}"`);
        if (fk.fromColumns.length === 0 || fk.fromColumns.length !== fk.toColumns.length) {
            throw new Error(`foreign key ${fk.name}: from/to columns must be non-empty and aligned`);
        }

        const fromColumns = fk.fromColumns.map((name) => {
            const column = from.columns.find((candidate) => candidate.name === name);
            if (!column) throw new Error(`foreign key ${fk.name}: unknown column "${name}"`);
            return column;
        });
        const toColumns = fk.toColumns.map((name) => {
            const column = to.columns.find((candidate) => candidate.name === name);
            if (!column) throw new Error(`foreign key ${fk.name}: unknown column "${name}"`);
            return column;
        });

        const composite = fromColumns.length > 1;
        const ambiguous = (pairCount.get(`${fk.fromTable}\u0000${fk.toTable}`) ?? 0) > 1;
        const suffixName = composite
            ? fromColumns.map((column) => column.name).join("_")
            : fromColumns[0]!.name;
        const suffix = ambiguous ? `_${suffixName}` : "";
        const names = [
            toSnakeCase(`${from.name}_${to.name}${suffix}`),
            toSnakeCase(`${to.name}_${from.name}${suffix}`),
        ];

        for (const name of names) {
            if (used.has(name)) {
                throw new Error(
                    `relation binding "${name}" collides with another generated binding`,
                );
            }
            used.add(name);
            bindings.push({ name, fk, from, to, fromColumns, toColumns, composite });
        }
    }

    bindings.sort((left, right) => left.name.localeCompare(right.name));

    const body: string[] = [];
    body.push("export struct RelationMeta {");
    for (const field of [
        "name: Str",
        "from_table: Str",
        "from_column: Str",
        "from_schema: Str",
        "to_table: Str",
        "to_column: Str",
        "to_schema: Str",
        "on_delete: Str",
        "on_update: Str",
    ]) {
        body.push(`  ${field}`);
    }
    body.push("}");
    body.push("");
    body.push("export struct CompositeRelationMeta {");
    for (const field of [
        "name: Str",
        "from_table: Str",
        "from_columns: List<Str>",
        "from_schema: Str",
        "to_table: Str",
        "to_columns: List<Str>",
        "to_schema: Str",
        "on_delete: Str",
        "on_update: Str",
    ]) {
        body.push(`  ${field}`);
    }
    body.push("}");
    body.push("");

    for (const binding of bindings) {
        const type = binding.composite ? "CompositeRelationMeta" : "RelationMeta";
        body.push(`export let ${binding.name}: ${type} = ${type}(`);
        body.push(`  name: ${ltString(binding.fk.name)},`);
        body.push(`  from_table: ${ltString(binding.from.dbName)},`);
        if (binding.composite) {
            body.push(
                `  from_columns: [${binding.fromColumns
                    .map((column) => ltString(column.dbName))
                    .join(", ")}],`,
            );
        } else {
            body.push(`  from_column: ${ltString(binding.fromColumns[0]!.dbName)},`);
        }
        body.push(`  from_schema: ${ltString(binding.from.schema)},`);
        body.push(`  to_table: ${ltString(binding.to.dbName)},`);
        if (binding.composite) {
            body.push(
                `  to_columns: [${binding.toColumns
                    .map((column) => ltString(column.dbName))
                    .join(", ")}],`,
            );
        } else {
            body.push(`  to_column: ${ltString(binding.toColumns[0]!.dbName)},`);
        }
        body.push(`  to_schema: ${ltString(binding.to.schema)},`);
        body.push(`  on_delete: ${ltString(binding.fk.onDelete ?? "NoAction")},`);
        body.push(`  on_update: ${ltString(binding.fk.onUpdate ?? "NoAction")},`);
        body.push(")");
        body.push("");
    }

    const single = bindings.filter((binding) => !binding.composite);
    const composite = bindings.filter((binding) => binding.composite);
    if (single.length > 0) {
        body.push(
            `export let all_relations: List<RelationMeta> = [${single
                .map((binding) => binding.name)
                .join(", ")}]`,
        );
        body.push("");
    }
    if (composite.length > 0) {
        body.push(
            `export let all_composite_relations: List<CompositeRelationMeta> = [${composite
                .map((binding) => binding.name)
                .join(", ")}]`,
        );
        body.push("");
    }

    const content = `${header("schema/schema.json")}package schema_relations {
${body.map((line) => (line.length > 0 ? `  ${line}` : "")).join("\n")}}
`;
    return { name: "schema_relations.lt", content };
}

export function emitLt(schema: SchemaIR): EmittedFile[] {
    const files: EmittedFile[] = [
        exprPackage(),
        ...SCALAR_SPECS.map((spec) => scalarPackage(spec)),
        unsupportedPackage(),
        metaPackage(),
        ...schema.enums.map((item) => enumPackage(item)),
    ];

    const nullableColumns = schema.tables.flatMap((table) =>
        table.columns.filter((column) => column.nullable && column.type !== "Unsupported"),
    );
    const nullableScalarTypes = new Set(
        nullableColumns
            .filter((column) => column.type !== "Enum")
            .map((column) => column.type),
    );
    for (const spec of SCALAR_SPECS) {
        if (nullableScalarTypes.has(spec.type)) files.push(scalarPackage(spec, true));
    }

    const nullableEnums = new Set(
        nullableColumns
            .filter((column) => column.type === "Enum")
            .map((column) => column.enum!),
    );
    for (const item of schema.enums) {
        if (nullableEnums.has(item.name)) files.push(enumPackage(item, true));
    }

    const tables = tablesPackage(schema);
    if (tables) files.push(tables);

    const relations = relationsPackage(schema);
    if (relations) files.push(relations);

    return files.sort((a, b) => a.name.localeCompare(b.name));
}
